1310	+// onboardingSetupSummary lists what "finish setup" still covers, one line per
1311	+// missing rung with its own benefit, under the same "N steps left" heading the
1312	+// closing checklist uses — so the prompt says exactly what is missing and what
1313	+// each step does. The import line names its real benefit: imported history is
1314	+// local-only (session list, explain) and does not appear in the web UI, so
1315	+// the web-UI promise must never attach to it.
1316	+func onboardingSetupSummary(missing []onboarding.Result) string {
1317	+	lines := make([]string, 0, len(missing))
1318	+	for _, r := range missing {
1319	+		switch r.Rung.Key {
1320	+		case onboarding.KeyAuth:
1321	+			lines = append(lines, "• Log in")
1322	+		case onboarding.KeyMirror:
1323	+			lines = append(lines, "• Mirror this repo")
1324	+		case onboarding.KeyImport:
1325	+			lines = append(lines, "• Import local sessions")
1326	+		}
1327	+	}
1328	+	if len(lines) == 0 {
1329	+		return ""
1330	+	}
1331	+	noun := "steps"
1332	+	if len(lines) == 1 {
1333	+		noun = "step"
1334	+	}
1335	+	return fmt.Sprintf("%d %s left:\n%s", len(lines), noun, strings.Join(lines, "\n"))
1336	+}
