1341	+// must not claim a web login or promise a browser: the login step
1342	+// authenticates the CLI (same as `entire auth login`), and headless/SSH
1343	+// terminals fall back to a device code. Deliberately terse — the checklist
1344	+// rows already carry each step's consequence.
1345	+func onboardingRungQuestion(r onboarding.Result) (title, description string) {
1346	+	switch r.Rung.Key {
1347	+	case onboarding.KeyAuth:
1348	+		return "Log in?", ""
1349	+	case onboarding.KeyMirror:
1350	+		return "Mirror this repo?", ""
1351	+	default:
1352	+		return "Set up " + r.Rung.Title + "?", r.Check.Detail
1353	+	}
1354	+}
