1395	+// mode unless the environment forces it). w is enable's output writer.
1396	+func runOnboardingLogin(ctx context.Context, w io.Writer) error {
1397	+	loginServer, err := parseLoginServer(api.DefaultAuthBaseURL)
1398	+	if err != nil {
1399	+		return fmt.Errorf("resolve login server: %w", err)
1400	+	}
