1411	+// runOnboardingImport is the import rung's offer, composing the enable-time
1412	+// import machinery from PR #1595: agent-scoped discovery, the optional
1413	+// per-agent picker, and best-effort per-agent imports (checkpoint policy and
1414	+// redaction config are enforced inside runSelectedImports). granular=true
1415	+// (step-by-step mode) shows the picker — Import/Skip confirm for one agent,
1416	+// multi-select for several, empty selection skips. granular=false imports
1417	+// everything eligible: the "set up everything" and --yes paths, where consent
1418	+// was already given.
1419	+func runOnboardingImport(ctx context.Context, w io.Writer, granular bool, scope []agent.Agent) error {
1420	+	repoRoot, err := paths.WorktreeRoot(ctx)
1421	+	if err != nil {
1422	+		return fmt.Errorf("resolve worktree root: %w", err)
1423	+	}
1424	+	if scope == nil {
1425	+		scope = installedImportAgents(ctx)
1426	+	}
1427	+	eligible := sessionImportDiscover(ctx, scope, repoRoot)
1428	+	if len(eligible) == 0 {
1429	+		return nil
1430	+	}
1431	+	selected := eligible
1432	+	if granular {
1433	+		selected, err = sessionImportPrompt(ctx, w, eligible)
1434	+		if err != nil {
1435	+			return fmt.Errorf("import selection: %w", err)
1436	+		}
1437	+		if len(selected) == 0 {
1438	+			return nil
1439	+		}
1440	+	}
1441	+	sessionImportRun(ctx, w, repoRoot, selected)
1442	+	return nil
