1445	+// installedImportAgents resolves the agents whose hooks are installed — the
1446	+// ladder's import scope. (#1595 scoped to the just-selected agents; the
1447	+// ladder runs on resume paths too, where "installed" is the equivalent set.)
1448	+func installedImportAgents(ctx context.Context) []agent.Agent {
1449	+	names := GetAgentsWithHooksInstalled(ctx)
1450	+	out := make([]agent.Agent, 0, len(names))
1451	+	for _, name := range names {
1452	+		if ag, err := agent.Get(name); err == nil {
1453	+			out = append(out, ag)
1454	+		}
1455	+	}
