1459	+// runOnboardingMirrorCreate is the mirror rung's offer: register the origin
1460	+// repo's mirror placement(s) using the create wizard's own machinery — the
1461	+// region multi-select pre-checked to the caller's jurisdiction
1462	+// (resolveOfferRegions) and the parallel per-region create (createMirrors) —
1463	+// so setup and `entire repo mirror create` resolve placements identically.
1464	+// Placements are registered without awaiting clones (`--no-wait` semantics),
1465	+// so enable never blocks on a large repo's clone.
1466	+func runOnboardingMirrorCreate(ctx context.Context, errW io.Writer, deps onboardingRungDeps) error {
1467	+	forge, owner, repo, err := deps.resolveOrigin(ctx)
1468	+	if err != nil {
1469	+		return fmt.Errorf("resolve origin: %w", err)
1470	+	}
1471	+	if forge != "gh" {
1472	+		return errors.New("origin is not a GitHub repository")
1473	+	}
1474	+	owner, repo = githubSlug(owner, repo)
1475	+	regions, err := resolveOfferRegions(ctx, errW)
1476	+	if err != nil {
1477	+		return err
1478	+	}
1479	+	targets := make([]mirrorTarget, 0, len(regions))
1480	+	for _, region := range regions {
1481	+		targets = append(targets, mirrorTarget{owner: owner, repo: repo, region: region})
1482	+	}
1483	+	results := createMirrors(ctx, errW, targets,
1484	+		true /* noWait: clones continue in the background */, 0)
1485	+	return finalizeMirrorOffer(errW, results)
1486	+}
1487	+
1488	+// finalizeMirrorOffer folds the per-region create results into the offer's
1489	+// outcome. Any serving placement is a success (the probe-cache write-through
1490	+// already happened inside createAndAwaitMirror); suspended-only placements
1491	+// are reported like `entire repo mirror create` does and return an error so
1492	+// the rung keeps its retry hint, as does a total failure.
1493	+func finalizeMirrorOffer(w io.Writer, results []mirrorResult) error {
1494	+	served, suspended := 0, 0
1495	+	var firstErr error
1496	+	for _, r := range results {
1497	+		switch r.status {
1498	+		case mirrorStatusSuspended:
1499	+			suspended++
1500	+		case mirrorStatusError:
1501	+			if firstErr == nil && r.err != nil {
1502	+				firstErr = r.err
1503	+			}
1504	+		default:
1505	+			served++
1506	+		}
1507	+	}
1508	+	if served > 0 {
1509	+		fmt.Fprintln(w, "  Mirror registered — the initial clone continues in the background.")
1510	+		return nil
1511	+	}
1512	+	if suspended > 0 {
1513	+		fmt.Fprintln(w, "  WARNING: this mirror has been suspended by an admin and won't be usable.")
1514	+		return errMirrorSuspended
1515	+	}
1516	+	if firstErr != nil {
1517	+		return firstErr
1518	+	}
1519	+	return errors.New("mirror placement not registered")
1520	+}
