2134	+// renderOnboardingChecklist renders the setup ladder for `entire status` and
2135	+// enable's closing summary. Fully connected collapses to a single line so the
2136	+// steady state stays quiet; anything less renders one row per applicable rung
2137	+// plus, when actionable steps remain, a pointer back at `entire enable`,
2138	+// which re-offers whatever is missing.
2139	+func renderOnboardingChecklist(results []onboarding.Result, sty statusStyles) string {
2140	+	if onboarding.Complete(results) {
2141	+		return renderConnectedLine(results, sty)
2142	+	}
2143	+
2144	+	done, total := onboarding.Summary(results)
2145	+	var b strings.Builder
2146	+	b.WriteString(sty.render(sty.bold, fmt.Sprintf("Setup %d/%d complete", done, total)))
2147	+	b.WriteString("\n")
2148	+
2149	+	titleWidth := 0
2150	+	for _, r := range results {
2151	+		if r.Check.State != onboarding.StateNotApplicable && len(r.Rung.Title) > titleWidth {
2152	+			titleWidth = len(r.Rung.Title)
2153	+		}
2154	+	}
2155	+	for _, r := range results {
2156	+		if r.Check.State == onboarding.StateNotApplicable {
2157	+			continue
2158	+		}
2159	+		b.WriteString("  ")
2160	+		b.WriteString(onboardingRowMarker(r.Check.State, sty))
2161	+		b.WriteString(" ")
2162	+		fmt.Fprintf(&b, "%-*s", titleWidth, r.Rung.Title)
2163	+		detail := r.Check.Detail
2164	+		// An unknown rung (e.g. offline mirror probe) doesn't count as a
2165	+		// missing step, so its hint would otherwise never surface — carry it
2166	+		// in the row instead of leaving a bare "?" with nothing actionable.
2167	+		if detail == "" && r.Check.State == onboarding.StateUnknown && r.Check.Hint != "" {
2168	+			detail = "couldn't check — retry with `" + r.Check.Hint + "`"
2169	+		}
2170	+		if detail != "" {
2171	+			b.WriteString("  ")
2172	+			b.WriteString(sty.render(sty.dim, detail))
2173	+		}
2174	+		b.WriteString("\n")
2175	+	}
2176	+
2177	+	if remaining := len(onboarding.Missing(results)); remaining > 0 {
2178	+		step := "steps"
2179	+		if remaining == 1 {
2180	+			step = "step"
2181	+		}
2182	+		b.WriteString(sty.render(sty.cyan,
2183	+			fmt.Sprintf("→ Run `entire enable` to finish setup (%d %s left)", remaining, step)))
2184	+		b.WriteString("\n")
2185	+	}
2186	+	return b.String()
2187	+}
