2189	+func onboardingRowMarker(state onboarding.State, sty statusStyles) string {
2190	+	switch state {
2191	+	case onboarding.StateDone:
2192	+		return sty.render(sty.green, "✓")
2193	+	case onboarding.StateMissing, onboarding.StateBlocked:
2194	+		return sty.render(sty.red, "✗")
2195	+	case onboarding.StateUnknown, onboarding.StateNotApplicable:
2196	+		return sty.render(sty.dim, "?")
