2525	+
2526	+// probeMirrorAcross asks each distinct core (deduped by origin) whether
2527	+// owner/repo is mirrored. A mirror found on any core counts: the active
2528	+// context's core and the default cluster the create offer targets can front
2529	+// different federations, and a mirror created on one is invisible to the
2530	+// other — probing only one would leave the rung re-offering creation
2531	+// forever. Errors matter only when every core is unreachable.
2532	+//
2533	+// The cores are probed concurrently, all under the caller's single deadline:
2534	+// probing them in sequence let a hanging core exhaust the shared budget and
2535	+// hand the next core an already-expired context, mis-reporting a healthy
2536	+// mirror as unknown — the exact cross-federation case the multi-core probe
2537	+// exists for. Fan-out keeps every core's window independent without growing
2538	+// the caller's overall wall-clock cap, and the first mirrored answer returns
2539	+// immediately — a hanging core must neither starve the others (finding
2540	+// 019fb390) nor hold a ready answer hostage until the deadline (finding
2541	+// 019fb42e). The results channel is buffered to len(cores), so stragglers
2542	+// finish into the buffer after an early return and the caller's cancel
2543	+// aborts their in-flight requests.
2544	+func probeMirrorAcross(ctx context.Context, clients []mirrorProbeClient, owner, repo string) (mirrorProbeResult, error) {
2545	+	seen := map[string]bool{}
2546	+	distinct := make([]mirrorProbeClient, 0, len(clients))
2547	+	for _, client := range clients {
2548	+		if client == nil || seen[client.CoreOrigin()] {
2549	+			continue
2550	+		}
2551	+		seen[client.CoreOrigin()] = true
2552	+		distinct = append(distinct, client)
2553	+	}
2554	+
2555	+	type coreAnswer struct {
2556	+		probe mirrorProbeResult
2557	+		err   error
2558	+	}
2559	+	results := make(chan coreAnswer, len(distinct))
2560	+	for _, client := range distinct {
2561	+		go func() {
2562	+			out, err := client.ListAvailableMirrors(ctx, coreapi.ListAvailableMirrorsParams{
2563	+				Owner: coreapi.NewOptString(owner),
2564	+			})
2565	+			if err != nil {
2566	+				results <- coreAnswer{err: err}
2567	+				return
2568	+			}
2569	+			for _, m := range out.Available {
2570	+				if strings.EqualFold(m.Owner, owner) && strings.EqualFold(m.Repo, repo) &&
2571	+					m.Status == coreapi.AvailableMirrorStatusMirrored {
2572	+					results <- coreAnswer{probe: mirrorProbeResult{
2573	+						Mirrored:  true,
2574	+						Suspended: mirrorSuspendedOn(ctx, client, owner, repo),
2575	+					}}
2576	+					return
2577	+				}
2578	+			}
2579	+			results <- coreAnswer{}
2580	+		}()
2581	+	}
2582	+
2583	+	var lastErr error
2584	+	answered := false
2585	+	for range distinct {
2586	+		a := <-results
2587	+		switch {
2588	+		case a.err != nil:
2589	+			lastErr = a.err
2590	+		case a.probe.Mirrored:
2591	+			return a.probe, nil
2592	+		default:
2593	+			answered = true
2594	+		}
2595	+	}
2596	+	if !answered {
2597	+		if lastErr == nil {
2598	+			lastErr = errors.New("no control-plane core reachable")
2599	+		}
2600	+		return mirrorProbeResult{}, fmt.Errorf("probe mirrors: %w", lastErr)
2601	+	}
2602	+	return mirrorProbeResult{}, nil
2603	+}
