2605	+// mirrorSuspendedOn reports whether every placement of owner/repo visible on
2606	+// this core is suspended. ListAvailableMirrors cannot express suspension —
2607	+// its status enum stops at "mirrored" — so a suspended placement reads as
2608	+// mirrored there; this follow-up read of the mirrors themselves keeps the
2609	+// checklist from showing a green rung for a mirror that will never serve.
2610	+// Best-effort and fail-open: an error, an absent status, or a listing that
2611	+// doesn't surface the placement all count as not suspended, so the probe's
2612	+// mirrored answer never degrades.
2613	+func mirrorSuspendedOn(ctx context.Context, client mirrorLister, owner, repo string) bool {
2614	+	mirrors, err := listMirrorsForRepo(ctx, client, mirrorCloneProviderGitHub, owner, repo)
2615	+	if err != nil {
2616	+		logging.Debug(ctx, "onboarding: mirror suspension check failed", "error", err)
2617	+		return false
2618	+	}
2619	+	if len(mirrors) == 0 {
2620	+		return false
2621	+	}
2622	+	for _, m := range mirrors {
2623	+		if m.Status.Or("") != coreapi.MirrorStatusSuspended {
2624	+			return false
2625	+		}
2626	+	}
2627	+	return true
2628	+}
