2641	+		if unreachable {
2642	+			return mirrorProbeResult{}, errors.New("control plane unreachable (cached)")
2643	+		}
2644	+		return probe, nil
2645	+	}
2646	+	ctx, cancel := context.WithTimeout(ctx, mirrorProbeTimeout)
2647	+	defer cancel()
