2649	+	if activeCore, err := coreapi.New(); err == nil {
2650	+		clients = append(clients, activeCore)
2651	+	}
2652	+	if clusterCore, err := coreapi.NewForCluster(ctx, defaultClusterHost); err == nil {
2653	+		clients = append(clients, clusterCore)
2654	+	}
2655	+	probe, err := probeMirrorAcross(ctx, clients, owner, repo)
2656	+	if err != nil {
2657	+		cache.putUnreachable(key, now)
