2664	+// discoverAgentImports reports, per registered importer, how much local
2665	+// transcript history exists for this repo and how much of it has never been
2666	+// imported. Discovery is file globbing; the expensive dry-run (checkpoint
2667	+// store open + transcript parsing) is memoized behind a fingerprint of the
2668	+// discovered files and the metadata-branch tip, so an unchanged repo pays
2669	+// only the glob on hot paths like `entire status`. Local-only, best-effort
2670	+// per agent.
2671	+func discoverAgentImports(ctx context.Context) ([]agentImportStatus, error) {
2672	+	repoRoot, err := paths.WorktreeRoot(ctx)
2673	+	if err != nil {
2674	+		return nil, fmt.Errorf("resolve worktree root: %w", err)
2675	+	}
2676	+	now := time.Now()
2677	+	type discovery struct {
2678	+		imp   agentimport.Importer
2679	+		files []agentimport.SessionFile
2680	+	}
2681	+	var discovered []discovery
2682	+	var inputs []importScanInput
2683	+	cacheable := true
2684	+	discoverFailures := 0
2685	+	// Scope to agents with hooks installed — the same set the import offer
2686	+	// acts on. Iterating every registered importer would report Missing for
2687	+	// history the offer will never import, an unresolvable checklist row.
2688	+	for _, ag := range installedImportAgents(ctx) {
2689	+		imp := importerForAgent(ag)
2690	+		if imp == nil {
2691	+			continue
2692	+		}
2693	+		files, discoverErr := imp.Discover(repoRoot, "", now, nil)
2694	+		if discoverErr != nil {
2695	+			// Best-effort per agent, but an error is not "nothing found":
2696	+			// don't memoize a result computed without this agent's files.
2697	+			logging.Warn(ctx, "onboarding: transcript discovery failed", "agent", imp.Name(), "error", discoverErr)
2698	+			discoverFailures++
2699	+			cacheable = false
2700	+			continue
2701	+		}
2702	+		if len(files) == 0 {
2703	+			continue
2704	+		}
2705	+		discovered = append(discovered, discovery{imp: imp, files: files})
2706	+		for _, f := range files {
2707	+			info, statErr := os.Stat(f.Path)
2708	+			if statErr != nil {
2709	+				// A file vanished between glob and stat — don't trust a
2710	+				// fingerprint built from a moving target.
2711	+				cacheable = false
2712	+				continue
2713	+			}
2714	+			inputs = append(inputs, importScanInput{Path: f.Path, ModTime: info.ModTime(), Size: info.Size()})
2715	+		}
2716	+	}
2717	+	if len(discovered) == 0 {
2718	+		if discoverFailures > 0 {
2719	+			// Every answer we have is an error — "no prior history found"
2720	+			// would be an affirmatively false settled state.
2721	+			return nil, fmt.Errorf("transcript discovery failed for %d agent(s)", discoverFailures)
2722	+		}
2723	+		return nil, nil
2724	+	}
2725	+
2726	+	repo, err := openRepository(ctx)
2727	+	if err != nil {
2728	+		return nil, err
2729	+	}
2730	+	defer repo.Close()
2731	+
2732	+	// The offer's import runner refuses to write under a restrictive
2733	+	// checkpoint policy; the rung must agree, or it reports Missing forever
2734	+	// while every consented offer silently skips.
2735	+	if policyErr := ensureCheckpointPolicyAllowsCheckpointData(ctx, repo); policyErr != nil {
2736	+		return nil, fmt.Errorf("%w: %w", errImportsPolicyRestricted, policyErr)
2737	+	}
2738	+
2739	+	tip, tipErr := metadataTip(repo)
2740	+	if tipErr != nil {
2741	+		// A digest computed without the checkpoint refs could collide with the
2742	+		// pre-import fingerprint and serve a stale "not imported" result.
2743	+		cacheable = false
2744	+	}
2745	+	fingerprint := importScanFingerprint(inputs, tip)
2746	+	cache := defaultImportScanCache()
2747	+	if cacheable {
2748	+		if statuses, ok := cache.get(repoRoot, fingerprint); ok {
2749	+			return statuses, nil
2750	+		}
2751	+	}
2752	+
2753	+	var statuses []agentImportStatus
2754	+	runFailures := 0
2755	+	for _, d := range discovered {
2756	+		res, runErr := agentimport.Run(ctx, repo, d.imp, agentimport.Options{
2757	+			RepoRoot: repoRoot, Now: now, DryRun: true,
2758	+		})
2759	+		if runErr != nil {
2760	+			// Best-effort per agent, but neither memoized (a partial result
2761	+			// would stay wrong until the fingerprint moves) nor silently
2762	+			// dropped: each agent is the sole source for its own history, so
2763	+			// a failed scan is recorded as such and the rung degrades
2764	+			// honestly instead of reporting Done/Missing with an undercount.
2765	+			logging.Warn(ctx, "onboarding: import dry-run failed", "agent", d.imp.Name(), "error", runErr)
2766	+			statuses = append(statuses, agentImportStatus{Agent: d.imp.Name(), ScanFailed: true})
2767	+			runFailures++
2768	+			cacheable = false
2769	+			continue
2770	+		}
2771	+		statuses = append(statuses, agentImportStatus{
2772	+			Agent:           d.imp.Name(),
2773	+			Sessions:        res.SessionsScanned,
2774	+			UnimportedTurns: res.TurnsImported,
2775	+			ImportedTurns:   res.TurnsSkipped,
2776	+		})
2777	+	}
2778	+	if runFailures == len(discovered) {
2779	+		// Every scan failed (typically one repo-level cause): report the
2780	+		// failure so the rung renders Unknown instead of a false
2781	+		// "no prior history found" / "N sessions imported".
2782	+		return nil, fmt.Errorf("import scan failed for all %d agent(s) with history", runFailures)
2783	+	}
2784	+	if cacheable {
2785	+		cache.put(repoRoot, fingerprint, statuses)
2786	+	}
2787	+	return statuses, nil
2788	+}
