2790	+// metadataTip identifies the local checkpoint-metadata state for the
2791	+// import-scan fingerprint: any new checkpoint or import moves it. Imports land
2792	+// on whichever backend is the configured primary, so both are covered — the
2793	+// v1 metadata branch tip plus the per-checkpoint refs the git-refs store
2794	+// writes (refs/entire/checkpoints/...), which never move the branch tip. The
2795	+// error reports a digest computed without the checkpoint refs; callers must
2796	+// not cache under it.
2797	+func metadataTip(repo *git.Repository) (string, error) {
2798	+	digest, err := checkpointRefsDigest(repo)
2799	+	return metadataBranchTip(repo) + "+" + digest, err
2800	+}
2801	+
2802	+// metadataBranchTip is the git-branch backend's tip (the v1 metadata branch).
2803	+func metadataBranchTip(repo *git.Repository) string {
2804	+	ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
2805	+	if err != nil {
2806	+		return "none"
2807	+	}
2808	+	return ref.Hash().String()
2809	+}
2810	+
2811	+// checkpointRefsDigest hashes the git-refs backend's per-checkpoint refs
2812	+// (name and hash), order-independently. An iteration failure returns the
2813	+// digest of whatever was seen plus the error.
2814	+func checkpointRefsDigest(repo *git.Repository) (string, error) {
2815	+	var lines []string
2816	+	iter, err := repo.References()
2817	+	if err == nil {
2818	+		err = iter.ForEach(func(ref *plumbing.Reference) error {
2819	+			if name := ref.Name().String(); strings.HasPrefix(name, checkpoint.CheckpointRefPrefix) {
2820	+				lines = append(lines, name+"|"+ref.Hash().String())
2821	+			}
2822	+			return nil
2823	+		})
2824	+	}
2825	+	sort.Strings(lines)
2826	+	h := sha256.New()
2827	+	for _, l := range lines {
2828	+		h.Write([]byte(l))
2829	+		h.Write([]byte{'\n'})
2830	+	}
2831	+	return hex.EncodeToString(h.Sum(nil)), err
2832	+}
