2908	+func importRung(deps onboardingRungDeps) onboarding.Rung {
2909	+	return onboarding.Rung{
2910	+		Key:   onboarding.KeyImport,
2911	+		Title: "History",
2912	+		Check: func(ctx context.Context) onboarding.Check {
2913	+			statuses, err := deps.discoverImports(ctx)
2914	+			if errors.Is(err, errImportsPolicyRestricted) {
2915	+				return onboarding.Check{
2916	+					State:  onboarding.StateNotApplicable,
2917	+					Detail: "imports restricted by checkpoint policy",
2918	+				}
2919	+			}
2920	+			if err != nil {
2921	+				return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire import"}
2922	+			}
2923	+			totalSessions := 0
2924	+			var unimported []agentImportStatus
2925	+			var scanFailed []string
2926	+			for _, s := range statuses {
2927	+				if s.ScanFailed {
2928	+					scanFailed = append(scanFailed, s.Agent)
2929	+					continue
2930	+				}
2931	+				totalSessions += s.Sessions
2932	+				if s.UnimportedTurns > 0 {
2933	+					unimported = append(unimported, s)
2934	+				}
2935	+			}
2936	+			if len(unimported) > 0 {
2937	+				// Pending imports stay actionable even when another agent's
2938	+				// scan failed — the offer is still worth running.
2939	+				return onboarding.Check{
2940	+					State:  onboarding.StateMissing,
2941	+					Detail: unimportedDetail(unimported),
2942	+					Hint:   importHint(unimported),
2943	+				}
2944	+			}
2945	+			if len(scanFailed) > 0 {
2946	+				// An agent with discovered history whose scan failed is the
2947	+				// sole source for its own counts — claiming Done (or "no
2948	+				// prior history") would overstate what is known.
2949	+				return onboarding.Check{
2950	+					State:  onboarding.StateUnknown,
2951	+					Detail: strings.Join(scanFailed, ", ") + " history scan failed",
2952	+					Hint:   "entire import",
2953	+				}
2954	+			}
2955	+			if totalSessions == 0 {
2956	+				return onboarding.Check{State: onboarding.StateNotApplicable, Detail: "no prior history found"}
2957	+			}
2958	+			return onboarding.Check{
2959	+				State:  onboarding.StateDone,
2960	+				Detail: fmt.Sprintf("%d sessions imported", totalSessions),
2961	+			}
2962	+		},
2963	+	}
2964	+}
