2966	+// importHint is the import rung's remediation command. With one agent pending
2967	+// it names that agent's import subcommand directly. With several there is
2968	+// only one hint slot, and naming just the first would read as "the import
2969	+// step is resolved" after running it — point at the group command instead,
2970	+// which lists the per-agent subcommands.
2971	+func importHint(unimported []agentImportStatus) string {
2972	+	if len(unimported) == 1 {
2973	+		return "entire import " + unimported[0].Agent
2974	+	}
2975	+	return "entire import"
2976	+}
2977	+
2978	+// unimportedDetail phrases the import rung's remaining work. When nothing was
2979	+// ever imported, session counts are accurate ("12 claude-code sessions found,
2980	+// not imported"). After a partial import, claiming every discovered session is
2981	+// unimported would overstate the work, so the wording switches to pending
2982	+// turns.
2983	+func unimportedDetail(unimported []agentImportStatus) string {
2984	+	agents := make([]string, 0, len(unimported))
2985	+	parts := make([]string, 0, len(unimported))
2986	+	sessions, pendingTurns, importedTurns := 0, 0, 0
2987	+	for _, s := range unimported {
2988	+		agents = append(agents, s.Agent)
2989	+		parts = append(parts, fmt.Sprintf("%d %s", s.Sessions, s.Agent))
2990	+		sessions += s.Sessions
2991	+		pendingTurns += s.UnimportedTurns
2992	+		importedTurns += s.ImportedTurns
2993	+	}
2994	+	if importedTurns > 0 {
2995	+		noun := "turns"
2996	+		if pendingTurns == 1 {
2997	+			noun = "turn"
2998	+		}
2999	+		return fmt.Sprintf("%s history partially imported (%d %s pending)",
3000	+			strings.Join(agents, ", "), pendingTurns, noun)
3001	+	}
3002	+	if sessions == 1 {
3003	+		return strings.Join(parts, ", ") + " session found, not imported"
3004	+	}
3005	+	return strings.Join(parts, ", ") + " sessions found, not imported"
3006	+}
